#!/usr/bin/env bash
# Run ONE experiment: `python train.py` under a timeout, log the result to experiments.tsv.
# Usage: ./run_experiment.sh "short description of what this experiment tries"
# DO NOT EDIT THIS FILE (the benchmark checks it is unchanged).
set -u
cd "$(dirname "$0")"
DESC="${1:-}"
# Budget + interpreter come from ../bench.env (written by the benchmark runner, outside this git repo); env vars
# are only a fallback, because some harnesses run shell commands in a clean environment.
[ -f ../bench.env ] && . ../bench.env
[ -f .bench/env ] && . ./.bench/env
TIMEOUT="${EXPERIMENT_TIMEOUT:-120}"
MAX="${MAX_EXPERIMENTS:-40}"
DEADLINE="${BENCH_DEADLINE_EPOCH:-0}"
PYTHON="${BENCH_PYTHON:-python}"
export BENCH_THREADS="${BENCH_THREADS:-4}" OMP_NUM_THREADS="${BENCH_THREADS:-4}"
TSV="experiments.tsv"
CPUB="${BENCH_CPU_BUDGET_S:-0}"                       # phase-2 budget: Python CPU seconds per cell (0 = off)
export BENCH_CPU_BUDGET_S="$CPUB" BENCH_LEDGER_DIR="${BENCH_LEDGER_DIR:-$(pwd)/../logs}"   # the ledger hook in train.py reads these
LEDGER="$BENCH_LEDGER_DIR/cpu_ledger.tsv"
cpu_used() { [ -f "$LEDGER" ] && awk -F'\t' 'NR>1{s+=$3} END{printf "%d", s}' "$LEDGER" || echo 0; }

[ -f "$TSV" ] || printf "n\tcommit\teval_auc\tstatus\tseconds\tdescription\n" > "$TSV"
# the count comes from the mirror outside the repo when it exists (a wiped workdir must not reset the budget)
if [ -n "${BENCH_EXPERIMENTS_MIRROR:-}" ] && [ -f "$BENCH_EXPERIMENTS_MIRROR" ]; then N=$(( $(wc -l < "$BENCH_EXPERIMENTS_MIRROR") - 1 ));
else N=$(( $(wc -l < "$TSV") - 1 )); fi
if [ "$N" -ge "$MAX" ]; then
  echo "BUDGET EXHAUSTED: $N/$MAX experiments used. Do not run more. Finalize now (see program.md)."
  exit 3
fi
if [ "$DEADLINE" -gt 0 ] && [ "$(date +%s)" -ge "$DEADLINE" ]; then
  echo "BUDGET EXHAUSTED: wall-clock limit reached. Finalize now (see program.md)."
  exit 3
fi
if [ "${CPUB%.*}" -gt 0 ] && [ "$(cpu_used)" -ge "${CPUB%.*}" ]; then
  echo "BUDGET EXHAUSTED: $(cpu_used) of ${CPUB%.*} CPU seconds of Python compute used. Do not run more. Finalize now (see program.md)."
  [ -f "$LEDGER" ] || printf "ts\tpid\tcpu_s\tkind\tevent\twall_s\tfits\targv\n" > "$LEDGER"
  printf "%s\t%s\t0.000\tcounted\trefused\t0.0\t0\trun_experiment.sh\n" "$(date +%s)" "$$" >> "$LEDGER"   # refusal is on the record too
  exit 3
fi

COMMIT=$(git rev-parse --short HEAD 2>/dev/null || echo "nogit")
if [ -n "$(git status --porcelain train.py 2>/dev/null)" ]; then COMMIT="${COMMIT}+dirty"; fi

run_with_timeout() {  # seconds cmd args...
  local t="$1"; shift
  if command -v timeout >/dev/null 2>&1; then timeout -k 10 "$t" "$@";
  elif command -v gtimeout >/dev/null 2>&1; then gtimeout -k 10 "$t" "$@";
  else perl -e 'alarm shift; exec @ARGV' "$t" "$@"; fi
}

START=$(date +%s)
export BENCH_COUNTED=1                                # this run is a counted experiment in the CPU ledger
run_with_timeout "$TIMEOUT" "$PYTHON" train.py > run.log 2>&1
RC=$?
unset BENCH_COUNTED
ELAPSED=$(( $(date +%s) - START ))

AUC=$(grep -E '^Eval AUC:' run.log | tail -1 | awk '{print $3}')
if [ "$RC" -eq 137 ] && [ "${ELAPSED%.*}" -lt "$TIMEOUT" ]; then STATUS="oom"; AUC="0.0000";   # SIGKILL well before the limit = the memory cap, not the clock
elif [ "$RC" -eq 124 ] || [ "$RC" -eq 137 ] || [ "$RC" -eq 142 ]; then STATUS="timeout"; AUC="${AUC:-0.0000}";
elif [ -z "$AUC" ]; then STATUS="crash"; AUC="0.0000";
else STATUS="ok"; fi

N=$((N + 1))
DESC_CLEAN=$(printf '%s' "$DESC" | tr '\t\n' '  ')
ROW="$(printf "%s\t%s\t%s\t%s\t%s\t%s" "$N" "$COMMIT" "$AUC" "$STATUS" "$ELAPSED" "$DESC_CLEAN")"
echo "$ROW" >> "$TSV"
# mirror outside the repo so no git command can erase the record
if [ -n "${BENCH_EXPERIMENTS_MIRROR:-}" ]; then
  [ -f "$BENCH_EXPERIMENTS_MIRROR" ] || head -1 "$TSV" > "$BENCH_EXPERIMENTS_MIRROR" 2>/dev/null
  echo "$ROW" >> "$BENCH_EXPERIMENTS_MIRROR" 2>/dev/null
fi

BEST=$(awk -F'\t' 'NR>1 && $4=="ok" && $3>m {m=$3} END {printf "%.4f", m+0}' "$TSV")
echo "experiment #$N  commit=$COMMIT  status=$STATUS  eval_auc=$AUC  best_so_far=$BEST  time=${ELAPSED}s"
LEFT=$((MAX - N))
MSG="budget: $LEFT experiments left"
if [ "$DEADLINE" -gt 0 ]; then MSG="$MSG, $(( (DEADLINE - $(date +%s)) / 60 )) minutes left"; fi
if [ "${CPUB%.*}" -gt 0 ]; then MSG="$MSG, CPU $(cpu_used)/${CPUB%.*} s used"; fi
echo "$MSG"
if [ "$STATUS" != "ok" ]; then echo "run failed ($STATUS, exit $RC): see tail -n 30 run.log"; fi
[ "$LEFT" -le 0 ] && echo "BUDGET EXHAUSTED: finalize now (see program.md)."
exit 0
